    m = normalized.match(/^Nivel\s+(\d+)\s+—\s+(.+)$/i);
    if (m) return byLang({ en: `Level ${m[1]} — ${m[2]}`, fr: `Niveau ${m[1]} — ${m[2]}`, de: `Level ${m[1]} — ${m[2]}`, it: `Livello ${m[1]} — ${m[2]}`, pt: `Nível ${m[1]} — ${m[2]}` });
    m = normalized.match(/^Nivel\s+(\d+)$/i);
    if (m) return byLang({ en: `Level ${m[1]}`, fr: `Niveau ${m[1]}`, de: `Level ${m[1]}`, it: `Livello ${m[1]}`, pt: `Nível ${m[1]}` });
    m = normalized.match(/^(.+)\s+compra a\s+(.+)\.$/i);
    if (m) return byLang({ en: `${m[1]} buys at ${m[2]}.`, fr: `${m[1]} achète à ${m[2]}.`, de: `${m[1]} kauft für ${m[2]}.`, it: `${m[1]} compra a ${m[2]}.`, pt: `${m[1]} compra a ${m[2]}.` });
    m = normalized.match(/^(.+)\s+se va:\s+muy caro\s+\(WTP\s+(.+)\)\.$/i);
    if (m) return byLang({ en: `${m[1]} leaves: too expensive (WTP ${m[2]}).`, fr: `${m[1]} part : trop cher (WTP ${m[2]}).`, de: `${m[1]} geht: zu teuer (WTP ${m[2]}).`, it: `${m[1]} se ne va: troppo caro (WTP ${m[2]}).`, pt: `${m[1]} vai embora: demasiado caro (WTP ${m[2]}).` });
    m = normalized.match(/^(.+)\s+se va:\s+sin stock\.$/i);
    if (m) return byLang({ en: `${m[1]} leaves: out of stock.`, fr: `${m[1]} part : rupture de stock.`, de: `${m[1]} geht: kein Bestand.`, it: `${m[1]} se ne va: scorte esaurite.`, pt: `${m[1]} vai embora: sem stock.` });
    m = normalized.match(/^Merma:\s+(\d+)\s+helados sin vender\.\s+Penalización\s+(.+)\.$/i);
    if (m) return byLang({ en: `Waste: ${m[1]} unsold ice creams. Penalty ${m[2]}.`, fr: `Perte : ${m[1]} glaces invendues. Pénalité ${m[2]}.`, de: `Verlust: ${m[1]} unverkaufte Eiscremes. Strafe ${m[2]}.`, it: `Spreco: ${m[1]} gelati invenduti. Penalità ${m[2]}.`, pt: `Perda: ${m[1]} gelados não vendidos. Penalização ${m[2]}.` });
    m = normalized.match(/^Frase\s+(.+)\s+de\s+(.+)$/i);
    if (m) return byLang({ en: `Phrase ${m[1]} of ${m[2]}`, fr: `Phrase ${m[1]} sur ${m[2]}`, de: `Satz ${m[1]} von ${m[2]}`, it: `Frase ${m[1]} di ${m[2]}`, pt: `Frase ${m[1]} de ${m[2]}` });
    m = normalized.match(/^Hay\s+(\d+)\s+letra(s?)\s+por revisar$/i);
    if (m) return byLang({
      en: `There ${m[1] === '1' ? 'is' : 'are'} ${m[1]} letter${m[1] === '1' ? '' : 's'} to review`,
      fr: `Il reste ${m[1]} lettre${m[1] === '1' ? '' : 's'} à vérifier`,
      de: `${m[1]} Buchstabe${m[1] === '1' ? '' : 'n'} zu prüfen`,
      it: `${m[1]} letter${m[1] === '1' ? 'a' : 'e'} da controllare`,
      pt: `${m[1]} letra${m[1] === '1' ? '' : 's'} por rever`
    });
    m = normalized.match(/^Queda(?:n)?\s+(\d+)\s+casilla(s?)$/i);
    if (m) return byLang({
      en: `${m[1]} square${m[1] === '1' ? '' : 's'} left`,
      fr: `Il reste ${m[1]} case${m[1] === '1' ? '' : 's'}`,
      de: `${m[1]} Feld${m[1] === '1' ? '' : 'er'} übrig`,
      it: `${m[1]} casell${m[1] === '1' ? 'a' : 'e'} rimast${m[1] === '1' ? 'a' : 'e'}`,
      pt: `Falta${m[1] === '1' ? '' : 'm'} ${m[1]} casa${m[1] === '1' ? '' : 's'}`
    });
    if (/^Saldo tras pedir:\s*€/.test(normalized)) {
      return normalized.replace('Saldo tras pedir:', byLang({ en: 'Balance after loan:', fr: 'Solde après emprunt :', de: 'Saldo nach dem Kredit:', it: 'Saldo dopo il prestito:', pt: 'Saldo após o empréstimo:' }));
    }
